import json,re,collections,csv
V=[json.loads(l) for l in open('meetings-07-advanced.p01.verdicts.jsonl')]
fix291='''@n1 syntax.nominal head="Mihai"
@n2 syntax.nominal dependent="Cedar" head="room"
@n3 syntax.nominal head="meeting"
@r1 syntax.relation marker="with" from=$n3 to=$n1
@r2 syntax.relation from=$n3 to=$n2
@c1 syntax.clause form=fragment complement=$n3'''
for v in V:
    if v['n']==291: v['sop']=fix291
with open('meetings-07-advanced.p01.verdicts.jsonl','w') as f:
    for v in V: f.write(json.dumps(v,ensure_ascii=False)+"\n")

rows={int(r['n']):r for r in csv.DictReader(open('meetings-07-advanced.p01.csv'))}
KEYS={'head','dependent','verb','auxiliary','negation','subject','complement','modifier','discourse','marker','conjunct','conjunction','ellipsis'}
def tok(s):
    return [w.strip('.') for w in re.findall(r"[A-Za-z0-9:>\-'’\.]+",s.lower())]
for v in V:
    s=v.get('sop')
    if not s: continue
    t=rows[v['n']]['text']
    toks=[]
    for m in re.finditer(r'(\w+)=("(?:[^"]*)"|\S+)',s):
        k,val=m.group(1),m.group(2)
        if k not in KEYS: continue
        val=val.strip('"')
        toks.extend(tok(val))
    tw=[w for w in tok(t) if w not in ('-','>','->','',')','(')]
    c1=collections.Counter(toks); c2=collections.Counter(tw)
    missing=[w for w in c2 if c1[w]<c2[w]]
    extra=[w for w in c1 if c1[w]>c2[w]]
    if missing or extra: print("n",v['n'],"missing",missing,"extra",extra)
print("check done; lines",len(V))
EOF"}

